 58→export async function syncSubscriptionFromShopify(
 59→  shop: string,
 60→  appSubscriptions: Array<{ id: string; name: string; status: string }>,
 61→): Promise<ShopSubscription> {
 62→  const activeSub = appSubscriptions.find((s) => s.status === "ACTIVE");
 63→
